create table if not exists spiritual.prayer_times ( id bigint generated always as identity primary key, calc_date date not null, latitude numeric(9,6) not null, longitude numeric(9,6) not null, method text not null references spiritual.prayer_methods (id), fajr timestamptz not null, sunrise timestamptz not null, dhuhr timestamptz not null, asr timestamptz not null, maghrib timestamptz not null, isha timestamptz not null, fajr_angle numeric(4,1) not null, isha_angle numeric(4,1), asr_method text not null default 'standard', calculated_by uuid not null references identity.profiles (id) default auth.uid(), tenant_id uuid references core.tenants (id), notes text, created_at timestamptz default now(), unique (calc_date, latitude, longitude, method) );
